/**
 * ASSET CONTRACT — shared between the Art team (produces files) and everyone else
 * (consumes texture keys / frame names).
 *
 * All runtime assets live in `public/assets/` and are listed in
 * `public/assets/manifest.json` (generated by `tools/art`). PreloadScene loads every
 * entry in the manifest, so adding an asset never requires code changes.
 *
 * Atlases use Phaser "JSON Hash" format. Animated frames are named `<anim>_<n>`
 * (n starting at 0), e.g. `walk_0 … walk_5`. AnimationSystem scans each atlas and
 * registers an animation `<atlasKey>:<anim>` for every `<anim>_<n>` group.
 *
 * Origins: character and enemy frames are bottom-centre anchored — the sprite's
 * feet touch the bottom row of the frame, horizontally centred. All frames in one
 * atlas share the same size. Sprites face RIGHT; code flips for left.
 */

export interface ManifestAtlas {
  key: string;
  png: string;
  json: string;
}
export interface ManifestImage {
  key: string;
  path: string;
}
export interface AssetManifest {
  atlases: ManifestAtlas[];
  images: ManifestImage[];
}

export const MANIFEST_PATH = 'assets/manifest.json';

/** Character atlases: key == CharacterId. Frames 48x48. */
export const CHARACTER_ANIMS = [
  'idle', // 4
  'walk', // 6
  'run', // 6
  'jump', // 2
  'fall', // 2
  'land', // 2
  'crouch', // 2
  'attack', // 4
  'hurt', // 2
  'victory', // 6
  'defeat', // 4
  'ability', // 2-6 — the character's special move
] as const;
export type CharacterAnim = (typeof CHARACTER_ANIMS)[number];
/** Single (non-animated) frame in every character atlas: 24x24 HUD portrait is a separate image `portrait-<id>`. */
export const CHARACTER_FRAME_SIZE = 48;

/** Enemy atlases: key == EnemyKind. Anims: idle, move, attack, hit, die (some enemies omit attack). */
export const ENEMY_ANIMS = ['idle', 'move', 'attack', 'hit', 'die'] as const;

